static std::string bytes(const QByteArray &s){return std::string(s.constData(),s.size());}
static QByteArray qb(const std::string &s){return QByteArray(s.data(),int(s.size()));}
static QString qs(const std::string &s){return QString::fromUtf8(s.data(),int(s.size()));}
static std::string stateFile(){return std::string(stateRoot())+"/state.json";}
static bool alive(const Json &j,Process *out=0){Process p;if(!process(j.num("native_pid"),p)||p.start!=j.num("native_starttime"))return false;if(out)*out=p;return true;}
static bool rebootCheck(){Json state,c,req;Authorization a;std::string error;Process worker;std::string generation;
 if(!loadConfig(c)||!loadJson(stateFile(),state,65536)||state.text("state")!="COMMITTED_PENDING_REBOOT"||state.num("confirmed")!=1||!loadAttempt(state.text("attempt_id"),c,a,req,error,true)||!rootReadOnly()||!noPowerRequest()||!closure(a.release.get("files"))||!readFile(std::string(runRoot())+"/boot.generation",generation,64)||generation!=state.text("boot_generation")||!process(state.num("worker_pid"),worker)||worker.start!=state.num("worker_starttime")||worker.exe!=bytes(QFile::encodeName(QCoreApplication::applicationFilePath())))return false;
 std::string result;if(!readFile(attemptPath(state.text("attempt_id"))+"/helper.result",result,65536)||result.find("result=committed root_rw=0")==std::string::npos)return false;
 int install=openFile("/user/pandanote/state/normal-install.lock",O_RDWR);if(install<0)return false;if(flock(install,LOCK_EX|LOCK_NB)){close(install);return false;}close(install);
 std::string lock=std::string(stateRoot())+"/reboot-"+state.text("attempt_id");int fd=openFile(lock,O_WRONLY|O_CREAT|O_EXCL);if(fd<0)return false;bool ok=!fsync(fd);close(fd);int d=open(stateRoot(),O_RDONLY|O_DIRECTORY|O_NOFOLLOW|O_CLOEXEC);ok=ok&&d>=0&&!fsync(d);if(d>=0)close(d);return ok;}
class OtaWorker:public QObject {
#ifdef PANDANOTE_OTA_FIXTURE
public:
#endif
 Json config,state,request_,response,ui;Authorization auth;DeviceHttp http;DeviceEndpoint endpoint;QByteArray token;QProcess helper;
 std::string action,eventPath,bootGeneration;int64_t retryAt,lastTick,healthSince,lastHealthPoll;int lease;bool configured,haveAuth,stopped,healthClosureChecked;std::string error_;
 std::string dir()const{return attemptPath(state.text("attempt_id"));}
 bool save(){if(atomic(stateFile(),encode(state)))return true;stopped=true;http.cancel();return false;}
 bool status(){Json j=state;j.object["schema"]=Json::integer(1);j.object["worker_heartbeat_ms"]=Json::integer(bootMs());Json b;std::string raw;if(baseline(b,raw))j.object["current_native_sha256"]=b.get("native_sha256");if(haveAuth){j.object["version"]=auth.release.get("version");j.object["sequence"]=auth.release.get("sequence");}return atomic(std::string(runRoot())+"/status.json",encode(j));}
 void fail(const std::string &code,bool recovery=false){error_=code;
 if(code=="authorization_expired"&&!recovery){http.cancel();action.clear();eventPath.clear();haveAuth=false;request_=Json();response=Json();auth=Authorization();state.object["confirmed"]=Json::integer(0);state.object["attempt_id"]=Json("");state.object["state"]=Json("IDLE");state.object["last_check"]=Json::integer(0);state.object["error_code"]=Json(code);state.object["generation"]=Json(randomHex(16));if(save())status();retryAt=bootMs()+60000;return;}
 if(code=="bundle_invalid"&&!recovery&&haveAuth){state.object["confirmed"]=Json::integer(0);state.object["state"]=Json("OFFERED");state.object["deferred"]=Json::integer(1);state.object["downloaded"]=Json::integer(0);}
http.cancel();action.clear();state.object["error_code"]=Json(code);if(recovery)state.object["state"]=Json("RECOVERY_REQUIRED");if(save()){queue();status();}retryAt=bootMs()+300000;}
 bool queue(){if(!haveAuth||(state.text("state")=="HEALTHY"&&state.text("error_code")!="none"))return true;Json e=Json::obj();std::string id=randomHex(16);if(id.empty()){stopped=true;return false;}e.object["schema"]=Json::integer(1);e.object["attempt_id"]=state.get("attempt_id");e.object["event_id"]=Json(id);e.object["sequence"]=auth.release.get("sequence");e.object["bundle_sha256"]=auth.deployment.get("bundle_sha256");e.object["state"]=state.get("state");e.object["error_code"]=state.get("error_code");std::string active,ready;if(!readFile("/user/pandanote/apps/current",active,128)||!readFile("/run/pandanote-normal/early.ready",ready,64)){stopped=true;return false;}if(!active.empty()&&active[active.size()-1]=='\n')active.resize(active.size()-1);if(!ready.empty()&&ready[ready.size()-1]=='\n')ready.resize(ready.size()-1);if(!hex(active)||!hex(ready,24)){stopped=true;return false;}e.object["active_native_sha256"]=Json(active);e.object["boot_id"]=Json(ready);std::string eventKey=state.text("attempt_id")+":"+state.text("state")+":"+state.text("error_code")+":"+active+":"+ready;if(state.text("last_event_key")==eventKey)return true;QDir d(qs(dir()+"/events"));if(d.entryList(QDir::Files|QDir::NoDotAndDotDot).size()>=64){stopped=true;return false;}if(!atomic(dir()+"/events/"+id+".json",encode(e))){stopped=true;return false;}state.object["last_event_key"]=Json(eventKey);return save();}
 bool transition(const std::string &s){state.object["state"]=Json(s);state.object["error_code"]=Json("none");return save()&&queue()&&status();}
 bool transport(){QByteArray raw;if(!readSyncFile("/user/pandanote/config/reader-sync.ini",4096,true,&raw))return false;QList<QByteArray> l=raw.split('\n');if(l.size()!=8||l[0]!="[sync]"||l[1]!="schema=1"||!l[2].startsWith("endpoint64=")||!l[3].startsWith("token64=")||!l[4].startsWith("certificate64=")||!l[5].startsWith("certificateSha256=")||!l[6].startsWith("bootstrapEpoch=")||!l[7].isEmpty())return false;QByteArray ep=QByteArray::fromBase64(l[2].mid(11)),tk=QByteArray::fromBase64(l[3].mid(8)),cert=QByteArray::fromBase64(l[4].mid(14));if(ep.toBase64()!=l[2].mid(11)||tk.toBase64()!=l[3].mid(8)||cert.toBase64()!=l[4].mid(14)||tk.size()<16||tk.size()>512||!QRegExp("[A-Za-z0-9._~-]+").exactMatch(QString::fromLatin1(tk)))return false;DeviceEndpoint e;QString error;if(!parseDeviceEndpoint(QString::fromUtf8(ep),&e,&error)||!e.tls)return false;QString cp=QString::fromUtf8(cert);if(!cp.startsWith("/user/pandanote/config/")||!readSyncFile(cp,16384,false,&e.certificatePem))return false;e.certificateSha256=QString::fromLatin1(l[5].mid(18));bool ok=false;e.bootstrapEpoch=l[6].mid(15).toLongLong(&ok);if(!ok||!QRegExp("[0-9a-f]{64}").exactMatch(e.certificateSha256)||!validTlsEpoch(e.bootstrapEpoch))return false;endpoint=e;token.fill('\0');token=tk;return true;}
 bool send(const std::string &kind,const Json &body,int limit){if(!configured&&!transport())return false;configured=true;if(ui.num("time_trusted")==1)http.trustEpoch(epoch());SyncRequest r;r.method="POST";r.path="/reader/v1/ota/"+qs(kind);r.body=qb(encode(body));r.limit=limit;QString error;if(!http.start(endpoint,token,r,&error)){retryAt=bootMs()+300000;return false;}action=kind;return true;}
 bool awake(){Json j;if(!loadJson(std::string(runRoot())+"/activity.json",j,4096)||!alive(j)||bootMs()-j.num("heartbeat_ms")>3000||j.num("heartbeat_ms")>bootMs()||j.text("boot_generation")!=bootGeneration)return false;ui=j;return j.num("awake")==1&&j.num("shutdown")==0;}
 bool armCheck(){if(ui.num("time_trusted")!=1){retryAt=bootMs()+60000;return false;}std::string error;if(!request(config,request_,error)){fail(error);return false;}std::string id=randomHex(16);if(id.empty())return false;std::string path=attemptPath(id);if(!directory(path,true)||!directory(path+"/events",true)||!atomic(path+"/request.json",encode(request_)))return false;state.object["attempt_id"]=Json(id);state.object["state"]=Json("CHECKING");state.object["confirmed"]=Json::integer(0);state.object["generation"]=Json(randomHex(16));haveAuth=false;return save()&&status();}
 bool validOffer(){Json req;Authorization verified;std::string error;if(loadAttempt(state.text("attempt_id"),config,verified,req,error)){request_=req;auth=verified;haveAuth=true;return true;}fail(error.empty()?"bundle_invalid":error);return false;}
 void commands(){Json j;std::string path=std::string(runRoot())+"/command.json";if(!loadJson(path,j,4096))return;removeFile(path);if(j.num("schema")!=1||j.text("generation")!=state.text("generation")||j.text("attempt_id")!=state.text("attempt_id"))return;std::string s=state.text("state"),a=j.text("action");if(!awake())return;if(s=="APPLYING"||s=="COMMITTED_PENDING_REBOOT"||s=="BOOT_VERIFYING"||s=="RECOVERY_REQUIRED"||s=="ROLLED_BACK")return;
 if(a=="check"&&(s=="IDLE"||s=="HEALTHY")){retryAt=0;armCheck();}
 else if(a=="show"&&s=="OFFERED"){state.object["deferred"]=Json::integer(0);save();status();}
 else if(a=="upgrade"&&s=="OFFERED"&&validOffer()){state.object["confirmed"]=Json::integer(1);state.object["downloaded"]=Json::integer(0);transition("DOWNLOADING");retryAt=0;}
 else if(a=="defer"&&(s=="OFFERED"||s=="DOWNLOADING"||s=="VERIFIED"||s=="WAITING_SAFE_WINDOW")){http.cancel();action.clear();state.object["confirmed"]=Json::integer(0);state.object["deferred"]=Json::integer(1);removeFile(std::string(runRoot())+"/prepare.request");transition("OFFERED");}
 }
 bool appendChunk(const std::string &body){int64_t done=state.num("downloaded");if(!checkpointChunk(dir()+"/bundle",done,auth.deployment.num("bundle_bytes"),body))return false;state.object["downloaded"]=Json::integer(done+body.size());return save()&&status();}
 void received(const std::string &kind,int statusCode,const std::string &body){if(kind=="report"){Json r;if(statusCode==200&&parse(body,r,4096)&&r.keys("schema,ok")&&r.num("schema")==1&&r.get("ok").type==Json::Boolean&&r.get("ok").number){removeFile(eventPath);eventPath.clear();}else retryAt=bootMs()+60000;if(eventPath.empty())retryAt=bootMs()+1250;return;}
 if(kind=="chunk"){if(statusCode!=200){fail(statusCode==404?"authorization_expired":"network_failure");return;}if(!appendChunk(body)){fail("bundle_invalid");return;}if(state.num("downloaded")==auth.deployment.num("bundle_bytes")){if(!validateBundle(dir()+"/bundle",auth)){fail("bundle_invalid");return;}transition("VERIFIED");}return;}
 Json r;if(!parse(body,r)||r.num("schema")!=1){fail("network_failure");return;}if(statusCode==202&&r.keys("schema,retry_seconds")&&r.num("retry_seconds")>=1&&r.num("retry_seconds")<=3600){retryAt=bootMs()+r.num("retry_seconds")*1000;return;}if(statusCode!=200){std::string code=r.get("error").text("code");if(statusCode==409&&(code=="grant_expired"||code=="nonce_conflict"||code=="release_revoked"))fail("authorization_expired");else fail(code=="baseline_mismatch"?"baseline_mismatch":"network_failure");return;}if(r.keys("schema,status")&&r.text("status")=="no_update"){state.object["last_check"]=Json::integer(epoch());state.object["attempt_id"]=Json("");state.object["state"]=Json("IDLE");state.object["error_code"]=Json("none");save();status();return;}
 Json ledger;std::string error;if(!loadJson(std::string(stateRoot())+"/accepted.json",ledger,4096)){fail("internal_error");return;}Json c=config;c.object["accepted_release_sha256"]=ledger.get("release_sha256");if(!authorize(r,c,request_,epoch(),auth,error)){fail(error);return;}haveAuth=true;response=r;if(!atomic(dir()+"/offer.json",body)||!atomic(dir()+"/candidate.json",auth.candidateRaw)){fail("storage_insufficient");return;}
 ledger.object["sequence"]=auth.release.get("sequence");ledger.object["release_sha256"]=Json(digest(auth.releaseRaw));if(!atomic(std::string(stateRoot())+"/accepted.json",encode(ledger))){fail("internal_error");return;}state.object["last_check"]=Json::integer(epoch());state.object["deferred"]=Json::integer(0);state.object["confirmed"]=Json::integer(0);transition("OFFERED");}
 bool space(){uint64_t user=auth.deployment.num("bundle_bytes"),root=0,home=2*1024*1024;unsigned nu=0,nr=0;for(size_t i=0;i<auth.release.get("files").array.size();i++){const Json &f=auth.release.get("files").array[i];if(f.text("role")=="release"||f.text("role")=="pointer"){user+=f.num("bytes");nu++;}else{root+=f.num("bytes");nr++;}if(f.text("role")=="entry"||f.text("role")=="pointer")home+=f.num("bytes");}uint64_t margin=user/5>8*1024*1024?user/5:8*1024*1024;int64_t downloaded=state.num("downloaded");if(downloaded>0&&uint64_t(downloaded)<=user)user-=downloaded;return freeSpace("/user",user+4096*nu+margin)&&freeSpace("/",root+4096*nr+1024*1024)&&freeSpace("/home",home);}
 void prepare(){if(state.num("confirmed")!=1)return;if(!safePower()){if(state.text("error_code")!="power_unsafe")fail("power_unsafe");return;}if(!noPowerRequest()||!awake()||ui.num("busy")!=0)return;Process n;std::string proof;if(!captureProof(proof,&n))return;Json q;if(!loadJson(std::string(runRoot())+"/prepare.request",q,4096)||q.text("attempt_id")!=state.text("attempt_id")||q.text("generation")!=state.text("generation")){q=processJson(n);q.object["schema"]=Json::integer(1);q.object["attempt_id"]=state.get("attempt_id");q.object["generation"]=state.get("generation");q.object["started_ms"]=Json::integer(bootMs());q.object["boot_generation"]=Json(bootGeneration);if(!atomic(std::string(runRoot())+"/prepare.request",encode(q)))fail("internal_error");return;}
 if(bootMs()-q.num("started_ms")>90000){state.object["confirmed"]=Json::integer(0);removeFile(std::string(runRoot())+"/prepare.request");transition("OFFERED");return;}
 if(!prepareValid(state.text("attempt_id"),state.text("generation"))||!space()||!rootReadOnly())return;
 if(!validOffer())return;
 if(!validateBundle(dir()+"/bundle",auth)||!atomic(dir()+"/proof",proof)){fail("proof_invalid");return;}std::string helperPath=config.text("helper_path"),hash;if(!hashFile(helperPath,hash)||hash!=auth.deployment.text("helper_sha256")){fail("signature_invalid");return;}if(!transition("APPLYING"))return;helper.setProcessChannelMode(QProcess::MergedChannels);helper.start(qs(helperPath),QStringList()<<"--apply"<<qs(state.text("attempt_id")));}
 void installed(){if(helper.state()!=QProcess::NotRunning)return;QByteArray output=helper.readAll();if(output.size()>65536||!atomic(dir()+"/helper.result",bytes(output))){fail("internal_error",true);return;}if(helper.exitStatus()!=QProcess::NormalExit||helper.exitCode()!=0||!output.contains("result=committed root_rw=0")||!rootReadOnly()||!closure(auth.release.get("files"))){std::string entry,current;if(output.contains("phase=rolled-back-root-ro")&&rootReadOnly()&&closure(auth.candidate.get("upgrade_from").get("old_files"))&&hashFile("/etc/inittab",entry)&&hashFile("/user/pandanote/apps/current",current)&&entry==auth.deployment.text("old_inittab_sha256")&&current==auth.deployment.text("old_current_sha256")){state.object["state"]=Json("ROLLED_BACK");state.object["error_code"]=Json("apply_failed");if(save()){queue();status();}}else fail("apply_failed",true);return;}state.object["commit_ms"]=Json::integer(bootMs());state.object["boot_generation"]=Json(bootGeneration);Process w;if(!process(getpid(),w)){fail("internal_error",true);return;}state.object["worker_pid"]=Json::integer(w.pid);state.object["worker_starttime"]=Json::integer(w.start);if(!transition("COMMITTED_PENDING_REBOOT"))return;Json r=Json::obj();r.object["schema"]=Json::integer(1);r.object["attempt_id"]=state.get("attempt_id");r.object["boot_generation"]=Json(bootGeneration);if(!atomic(std::string(runRoot())+"/reboot.request",encode(r)))fail("reboot_failed",true);}
 void health(){if(bootMs()-lastHealthPoll<1000)return;lastHealthPoll=bootMs();if(!rootReadOnly()||(!healthClosureChecked&&!closure(auth.release.get("files")))){fail("health_failed",true);return;}healthClosureChecked=true;Json h;Process n;
 // 健康确认绑定重启后的新鲜 native 身份，拒绝安装前标记。
 if(loadJson(std::string(runRoot())+"/health.ready",h,4096)&&h.text("boot_generation")==bootGeneration&&h.text("native_sha256")==auth.release.text("native_sha256")&&h.num("paint_count")>0&&h.num("workspace_ready")==1&&h.num("event_loop_ready")==1&&alive(h,&n)&&bootMs()-h.num("heartbeat_ms")<=3000&&h.num("heartbeat_ms")<=bootMs()&&n.exe=="/user/pandanote/apps/releases/"+auth.release.text("native_sha256")+"/reader-shell.mipsel"){
 if(healthSince<0)healthSince=bootMs();if(bootMs()-healthSince>=60000){if(!closure(auth.release.get("files"))){fail("health_failed",true);return;}if(!atomic(std::string(stateRoot())+"/baseline.json",auth.candidateRaw)){fail("internal_error",true);return;}transition("HEALTHY");removeFile(std::string(runRoot())+"/prepare.request");return;}}
 else healthSince=-1;if(bootMs()-state.num("health_started_ms")>=180000)fail("health_failed",true);}
 void report(){QDir attempts(qs(std::string(stateRoot())+"/attempts"));QStringList ids=attempts.entryList(QDir::Dirs|QDir::NoDotAndDotDot,QDir::Name);for(int i=0;i<ids.size();++i){std::string path=attemptPath(bytes(ids[i].toLatin1()));if(path.empty())continue;QDir d(qs(path+"/events"));QStringList names=d.entryList(QStringList()<<"*.json",QDir::Files,QDir::Name);if(names.isEmpty())continue;Json e;eventPath=path+"/events/"+bytes(names.first().toLatin1());if(loadJson(eventPath,e,4096))send("report",e,4096);else fail("internal_error",true);return;}}
protected:
 void timerEvent(QTimerEvent*){if(stopped)return;int64_t now=bootMs();if(now-lastTick>=1000){lastTick=now;status();}commands();if(stopped)return;std::string s=state.text("state");if(s=="APPLYING"){installed();return;}if(s=="BOOT_VERIFYING"){health();if(stopped)return;s=state.text("state");}
 if(s=="COMMITTED_PENDING_REBOOT"){if(now-state.num("commit_ms")>60000)fail("reboot_failed",true);return;}
 if(!awake()&&s!="RECOVERY_REQUIRED"&&s!="ROLLED_BACK"){if(http.busy()){http.cancel();action.clear();}return;}
 int code=0;QByteArray body;QString err;int result=http.poll(&code,&body,&err);if(result){std::string kind=action;action.clear();if(result<0){if(kind=="report")retryAt=bootMs()+60000;else fail("network_failure");return;}received(kind,code,bytes(body));return;}if(http.busy()||now<retryAt)return;
 if(s=="RECOVERY_REQUIRED"||s=="ROLLED_BACK"){report();return;}
 if(s=="IDLE"||s=="HEALTHY"){report();if(http.busy())return;if(due(epoch(),state.num("last_check"))&&armCheck())send("check",request_,786432);return;}
 if(s=="CHECKING"){send("check",request_,786432);return;}
 if(s=="OFFERED"){if(haveAuth&&auth.deployment.num("expires_at")<=epoch()&&due(epoch(),state.num("last_check"))){state.object["confirmed"]=Json::integer(0);armCheck();return;}report();return;}
 if(s=="DOWNLOADING"){if(!haveAuth||!validOffer())return;if(state.num("downloaded")==auth.deployment.num("bundle_bytes")){if(validateBundle(dir()+"/bundle",auth))transition("VERIFIED");else fail("bundle_invalid");return;}if(state.num("confirmed")!=1)return;if(!space()){fail("storage_insufficient");return;}Json r=Json::obj();r.object["schema"]=Json::integer(1);r.object["bundle_sha256"]=auth.deployment.get("bundle_sha256");r.object["index"]=Json::integer(state.num("downloaded")/262144);send("chunk",r,262144);return;}
 if(s=="VERIFIED"){transition("WAITING_SAFE_WINDOW");return;}if(s=="WAITING_SAFE_WINDOW"){prepare();return;}}
public:
 OtaWorker():retryAt(0),lastTick(0),healthSince(-1),lastHealthPoll(0),lease(-1),configured(false),haveAuth(false),stopped(false),healthClosureChecked(false){}
 bool init(){if(!loadConfig(config)||!directory(stateRoot())||!directory(std::string(stateRoot())+"/attempts")||!directory(runRoot(),true))return false;lease=openFile(std::string(stateRoot())+"/worker.lock",O_RDWR|O_CREAT);if(lease<0||flock(lease,LOCK_EX|LOCK_NB))return false;
 if(!readFile("/run/pandanote-normal/ota/boot.generation",bootGeneration,64)){bootGeneration=randomHex(16);if(bootGeneration.empty()||!atomic(std::string(runRoot())+"/boot.generation",bootGeneration))return false;}
 if(!hex(bootGeneration,32))return false;
 if(!loadJson(stateFile(),state,65536)||state.num("schema")!=1||!hex(state.text("generation"),32))return false;std::string s=state.text("state"),error;
 if(!state.text("attempt_id").empty()&&s!="CHECKING"){haveAuth=loadAttempt(state.text("attempt_id"),config,auth,request_,error,true);if(!haveAuth)return false;}
 if(s=="CHECKING"){if(!loadJson(dir()+"/request.json",request_,4096))return false;haveAuth=false;}
 else if(s=="APPLYING"){fail("recovery_required",true);}
 else if(s=="COMMITTED_PENDING_REBOOT"||s=="BOOT_VERIFYING"){std::string ready;bool active=readFile("/run/pandanote-normal/early.ready",ready,64)&&ready==auth.release.text("boot_id")+"\n";std::string next=resumeState(s,state.text("boot_generation")!=bootGeneration,active);if(next=="RECOVERY_REQUIRED")fail("health_failed",true);else if(s!=next){state.object["boot_generation"]=Json(bootGeneration);state.object["health_started_ms"]=Json::integer(bootMs());transition("BOOT_VERIFYING");}}

 else if(s!="IDLE"&&s!="HEALTHY"&&s!="OFFERED"&&s!="DOWNLOADING"&&s!="VERIFIED"&&s!="WAITING_SAFE_WINDOW"&&s!="RECOVERY_REQUIRED"&&s!="ROLLED_BACK")return false;
 state.object["generation"]=Json(randomHex(16));if(!save()||!status())return false;startTimer(250);return true;}
};
