int main(int argc,char **argv){if(argc==3&&!strcmp(argv[1],"--resolve-host"))return runDnsWorker(argv[2]);QCoreApplication app(argc,argv);if(argc==2&&!strcmp(argv[1],"--reboot-check"))return rebootCheck()?0:1;if(argc!=1)return 2;OtaWorker worker;if(!worker.init())return 3;return app.exec();}

#endif
